<template><div class="space-y-3 p-4"><h1 class="text-xl font-bold text-slate-800">Compare offers</h1><div v-for="offer in offers" :key="offer.id" class="m-card"><div class="flex justify-between"><p class="text-sm font-semibold text-slate-800">{{ money(offer.price_minor, offer.currency) }}</p><span class="status-pill bg-indigo-50 text-indigo-600">{{ offer.status }}</span></div><p class="mt-2 text-xs text-slate-400">{{ offer.terms_json || 'Standard supplier terms' }}</p><button v-if="offer.status === 'submitted'" class="m-btn-primary mt-4" @click="award(offer.id)">Award offer</button></div><p v-if="error" class="m-card text-sm text-red-600">{{ error }}</p></div></template>
<script setup lang="ts">
definePageMeta({ middleware: ['auth'] }); const route = useRoute(); const api = useCommerce(); const requestId = String(route.query.request_id || ''); const offers = ref<any[]>([]); const error = ref(''); const money = (value: number, currency: string) => new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(value / 100); async function award(id: string) { try { const order = await api.awardOffer(id); await navigateTo(`/buyer/orders/${order.id}`) } catch (e: any) { error.value = e?.data?.detail || e?.message } } onMounted(async () => { try { if (!requestId) throw new Error('Select a request first'); offers.value = (await api.listOffers(requestId)).items } catch (e: any) { error.value = e?.data?.detail || e?.message } })
</script>
